{"formatVersion":3,"title":"Coffee Cup Counter","description":"Counts cups of coffee and beeps each time you add one.","capabilities":["audio.tone"],"capabilityResults":false,"stateSchema":{"count":"number","mute":"boolean"},"initialState":{"count":0,"mute":false},"ui":{"type":"column","children":[{"type":"metric","text":"Cups added","bind":"count","style":{"emphasis":"number"}},{"type":"button","text":"Add cup","action":"add","variant":"filled"},{"type":"button","text":"Reset","action":"reset","variant":"outlined"},{"type":"toggle","text":"Mute beep","bind":"mute","action":"muteToggle"},{"type":"text","text":"Each cup adds one and plays a short beep."}]},"behaviorBindings":{"add":"add","reset":"reset","muteToggle":"muteToggle","mute":[3],"count":[0]},"source":"const event = input.event || {};
const state = input.state;
const count = Number(state.count) || 0;
const mute = state.mute === true;

if (event.type === 'action') {
  if (event.actionId === 'add') {
    const next = { count: count + 1, mute: mute };
    if (mute) return { state: next };
    return {
      state: next,
      effects: [{ id: 'beep', capability: 'audio.tone', args: { tone: 'beep', durationMillis: 150 } }]
    };
  }
  if (event.actionId === 'reset') {
    return { state: { count: 0, mute: mute } };
  }
  if (event.actionId === 'muteToggle') {
    const nextMute = typeof event.value === 'boolean' ? event.value : !mute;
    return { state: { count: count, mute: nextMute } };
  }
  return { state: state };
}

return { state: state };"}
